const DEPARTMENTS=[
 {id:'men',name:'رجالي',en:'MEN’S DEPARTMENT',x:13,preview:'p6',description:'ملابس يومية، بتفاصيل مختلفة.'},
 {id:'women',name:'نسائي',en:'WOMEN’S DEPARTMENT',x:34,preview:'p5',description:'قطع مختارة لكل إطلالة.'},
 {id:'shoes',name:'أحذية',en:'THE FOOTWEAR ROOM',x:71,preview:'p11',description:'خطوتك القادمة تبدأ هنا.'},
 {id:'bags',name:'حقائب',en:'THE BAG GALLERY',x:93,preview:'p15',description:'تفاصيل ترافق كل يوم.'},
 {id:'accessories',name:'إكسسوارات',en:'THE FINISHING TOUCH',x:56,preview:'p17',description:'التفاصيل الصغيرة تصنع الفرق.'}
];
let roomProducts=[],roomIndex=0,roomCategory='all',currentDepartment=null,roomDrag=null,roomDragging=false,mallScrolled=false;
function departmentProducts(id){if(['men','women'].includes(id))return PRODUCTS.filter(p=>p.gender.includes(id)&&['tops','outerwear','knit','bottoms'].includes(p.category));return PRODUCTS.filter(p=>p.category===id)}
function departmentNav(active='all'){return `<nav class="mall-departments" aria-label="أقسام المحل"><a class="${active==='all'?'active':''}" href="#home">كل الأقسام</a>${DEPARTMENTS.map(d=>`<a href="#room/${d.id}" class="${active===d.id?'active':''}">${d.name}</a>`).join('')}</nav>`}
function home(){return walkHome()}
function roomPage(id){currentDepartment=DEPARTMENTS.find(d=>d.id===id)||DEPARTMENTS[0];roomCategory='all';roomIndex=0;roomProducts=departmentProducts(currentDepartment.id);roomIndex=Math.min(2,roomProducts.length-1);const cats=[...new Set(roomProducts.map(p=>p.category))];return `<section data-section="${currentDepartment.id}" class="room-experience ${['shoes','bags','accessories'].includes(id)?'object-room':''}" aria-label="المساحة التفاعلية لقسم ${currentDepartment.name}"><img class="room-background" src="assets/loop-shop-interior.png" alt="أقسام العرض داخل محل LOOP" draggable="false"><div class="room-top"><a href="#home" class="room-back">${icon('arrow')} العودة للمحل</a><div><span class="mall-kicker">${currentDepartment.name} / ${currentDepartment.en}</span><h1 class="room-brand-name">${shopBrand(currentDepartment.id).brand}</h1><p>LOOP · جميع الأقسام في محل واحد</p></div><button data-action="mall-map" class="room-switch">تغيير القسم ${icon('menu')}</button></div><div id="immersiveStage" class="immersive-stage" aria-label="تصفح المنتجات بالسحب أو الأسهم"><div class="display-rail"></div><div class="display-platform"></div><div id="immersiveRack" class="immersive-rack"></div><button data-action="room-prev" class="room-arrow room-prev" aria-label="القطعة السابقة">←</button><button data-action="room-next" class="room-arrow room-next" aria-label="القطعة التالية">→</button></div><div class="room-product-strip" id="roomProductStrip" aria-live="polite"></div><div class="room-bottom"><div class="room-browse-hint"><span>←</span> اسحب لاستكشاف القطع <span>→</span></div><nav id="roomCategories" class="room-categories" aria-label="تصنيفات قسم ${currentDepartment.name}"><button class="active" data-action="room-category" data-category="all">الكل</button>${cats.length>1?cats.map(c=>`<button data-action="room-category" data-category="${c}">${catName(c)}</button>`).join(''):`<button data-action="room-category" data-category="new">الجديد</button><button data-action="room-category" data-category="sale">العروض</button>`}</nav><span id="roomCounter" class="room-counter"></span><button data-action="room-list" class="room-list-button">كل قطع القسم ${icon('menu')}</button></div></section>`}
function setupMall(){setupWalk()}
function setupRoom(){renderRoomRack();const rack=document.getElementById('immersiveRack');if(!rack)return;rack.addEventListener('pointerdown',e=>{if(e.button!==0)return;roomDrag={x:e.clientX,y:e.clientY,pointer:e.pointerId};roomDragging=false;rack.setPointerCapture(e.pointerId)});rack.addEventListener('pointermove',e=>{if(roomDrag&&Math.abs(e.clientX-roomDrag.x)>12){roomDragging=true;rack.classList.add('dragging')}});rack.addEventListener('pointerup',e=>{if(!roomDrag)return;const dx=e.clientX-roomDrag.x;if(Math.abs(dx)>35)moveRoom(dx>0?-1:1);else if(!roomDragging){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-room-index]');if(target)selectRoomItem(+target.dataset.roomIndex)}roomDrag=null;rack.classList.remove('dragging')});rack.addEventListener('pointercancel',()=>{roomDrag=null;roomDragging=false;rack.classList.remove('dragging')})}
function isShelfSection(){return ['shoes','bags','accessories'].includes(currentDepartment?.id)}
function sectionShelfMarkup(){const first=Math.floor(roomIndex/4)*4;return roomProducts.slice(first,first+4).map((p,i)=>`<button class="shop-shelf-product ${first+i===roomIndex?'focused':''}" data-room-index="${first+i}" aria-label="${p.name}، ${p.color}" aria-pressed="${first+i===roomIndex}"><span class="shelf-product-art">${sprite(p)}</span><span class="shelf-ticket">${p.name}<small>${money(p.price)}</small></span><span class="wood-shelf"></span></button>`).join('')}
function renderRoomRack(){const rack=document.getElementById('immersiveRack');if(!rack)return;rack.classList.toggle('shop-shelf-grid',isShelfSection());rack.innerHTML=isShelfSection()?sectionShelfMarkup():roomProducts.map((p,i)=>`<button class="room-piece" data-room-index="${i}" aria-label="${p.name}، ${p.color}، ${money(p.price)}">${sprite(p)}</button>`).join('');layoutRoom();}
function layoutRoom(){const rack=document.getElementById('immersiveRack');if(!rack||!roomProducts.length)return;if(isShelfSection()){rack.innerHTML=sectionShelfMarkup()}else{const stage=document.getElementById('immersiveStage'),width=stage.clientWidth,mobile=width<760,piece=Math.min(mobile?width*.7:width*.29,stage.clientHeight*.91,mobile?300:370),step=mobile?Math.max(piece*.78,width*.48):Math.min(245,piece*.78);rack.style.setProperty('--piece-size',piece+'px');stage.style.setProperty('--piece-size',piece+'px');document.querySelectorAll('.room-piece').forEach((el,i)=>{const d=i-roomIndex;el.style.transform=`translateX(${d*step}px) scale(${d===0?1.08:Math.max(.6,.82-Math.abs(d)*.035)}) rotate(${d===0?0:d<0?-2:2}deg)`;el.style.zIndex=10-Math.abs(d);el.style.opacity=Math.abs(d)>3?'0':d===0?'1':'.7';el.style.visibility=Math.abs(d)>3?'hidden':'visible';el.tabIndex=Math.abs(d)>1?-1:0;el.classList.toggle('focused',d===0)})}const p=roomProducts[roomIndex];document.getElementById('roomProductStrip').innerHTML=`<div class="room-selected-info"><span>${catName(p.category)} / ${p.color}</span><h2>${p.name}</h2><strong>${money(p.price)}</strong></div><button class="room-details" data-action="quick" data-id="${p.id}">تفاصيل القطعة ↗</button>${heart(p,'room-heart')}`;document.getElementById('roomCounter').textContent=String(roomIndex+1).padStart(2,'0')+' / '+String(roomProducts.length).padStart(2,'0');}
function selectRoomItem(i){if(i===roomIndex)openQuick(roomProducts[i].id);else{roomIndex=i;layoutRoom()}}
function moveRoom(direction){if(roomProducts.length<2)return;roomIndex=(roomIndex+direction+roomProducts.length)%roomProducts.length;layoutRoom()}
function filterRoom(category){roomCategory=category;const all=departmentProducts(currentDepartment.id);roomProducts=all.filter(p=>category==='all'||category==='new'&&p.new||category==='sale'&&p.oldPrice||p.category===category);roomIndex=0;document.querySelectorAll('#roomCategories button').forEach(b=>b.classList.toggle('active',b.dataset.category===category));renderRoomRack();if(!roomProducts.length){document.getElementById('roomProductStrip').innerHTML='<p>لا توجد قطع ضمن هذا التصنيف حالياً.</p>';document.getElementById('roomCounter').textContent='00 / 00'}}
function mallMap(){modal(`<div class="mall-map-content"><span class="eyebrow">CHOOSE YOUR DESTINATION</span><h2>أقسام محل LOOP</h2><p>اختر علاقات الملابس أو رفوف الأحذية والحقائب أو طاولة الإكسسوارات.</p><div class="map-departments">${DEPARTMENTS.map((d,i)=>`<a href="#room/${d.id}"><div class="map-preview">${sprite(product(d.preview))}</div><div><small>0${i+1} / ${departmentProducts(d.id).length} قطعة</small><h3>${d.name}</h3></div><span>←</span></a>`).join('')}</div><a class="text-link" href="#home">العودة إلى المحل ←</a></div>`)}
function roomList(){modal(`<div class="mall-map-content"><span class="eyebrow">${currentDepartment.en}</span><h2>قطع قسم ${currentDepartment.name}</h2><p>اختر قطعة لعرضها في المساحة التفاعلية.</p><div class="room-piece-picker">${roomProducts.map((p,i)=>`<button data-action="room-jump" data-index="${i}"><span>${sprite(p)}</span><strong>${p.name}</strong><small>${p.color} / ${money(p.price)}</small></button>`).join('')}</div></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='mall-map')mallMap();if(a==='room-list')roomList();if(a==='room-prev')moveRoom(-1);if(a==='room-next')moveRoom(1);if(a==='room-category')filterRoom(b.dataset.category);if(a==='room-jump'){roomIndex=+b.dataset.index;closeLayers();layoutRoom()}if(a==='mall-pan'){const pane=document.getElementById('mallPanorama');pane?.scrollBy({left:+b.dataset.direction*260,behavior:'smooth'})}});
document.addEventListener('keydown',e=>{if(!location.hash.startsWith('#room/')||!document.getElementById('modal').hidden||!document.getElementById('drawer').hidden)return;if(e.key==='ArrowLeft'){e.preventDefault();moveRoom(-1)}if(e.key==='ArrowRight'){e.preventDefault();moveRoom(1)}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-room-index]')){e.preventDefault();selectRoomItem(+e.target.dataset.roomIndex)}});
window.addEventListener('resize',()=>{if(location.hash.startsWith('#room/'))layoutRoom();else if(!location.hash||location.hash==='#home')setupMall()});
